+                <button class="page-link" @onclick="@(() => OnPageChanged.InvokeAsync(Page - 1))"
+                        disabled="@(Page <= 1)">Previous</button>
+            </li>
+
+            @foreach (var p in GetPageNumbers())
+            {
+                <li class="page-item @(p == Page ? "active" : "")">
+                    <button class="page-link" @onclick="@(() => OnPageChanged.InvokeAsync(p))">@p</button>
+                </li>
+            }
+
+            <li class="page-item @(Page >= TotalPages ? "disabled" : "")">
+                <button class="page-link" @onclick="@(() => OnPageChanged.InvokeAsync(Page + 1))"
+                        disabled="@(Page >= TotalPages)">Next</button>
+            </li>
+        </ul>
+    </nav>
+}
+
+@code {
+    [Parameter]
+    public int Page { get; set; }
+
+    [Parameter]
+    public int TotalPages { get; set; }
+
+    [Parameter]
+    public EventCallback<int> OnPageChanged { get; set; }
+
+    private IEnumerable<int> GetPageNumbers()
+    {
+        const int maxVisible = 5;
+        int startPage = Math.Max(1, Page - maxVisible / 2);
+        int endPage = Math.Min(TotalPages, startPage + maxVisible - 1);
+        startPage = Math.Max(1, endPage - maxVisible + 1);
+
+        return Enumerable.Range(startPage, endPage - startPage + 1);
+    }
+}
