@page "/catalog"
@using sv_83834c64a8bd4fe0a6f1ea79f1bde4f4.Services
@rendermode InteractiveServer
@inject IProductService ProductService

<PageTitle>Product Catalog</PageTitle>

<h3 class="mb-3">Product Catalog</h3>

<div class="row">
    <!-- Sidebar -->
    <div class="col-lg-3 mb-3">
        <CatalogSidebar Categories="categories"
                        CurrentFilter="filter"
                        OnApplyFilters="HandleApplyFilters"
                        OnClearFilters="HandleClearFilters" />
    </div>

    <!-- Main Content -->
    <div class="col-lg-9">
        @if (loading)
        {
            <div class="d-flex justify-content-center p-5">
                <div class="spinner-border text-primary" role="status">
                    <span class="visually-hidden">Loading...</span>
                </div>
            </div>
        }
        else if (errorMessage is not null)
        {
            <div class="alert alert-danger" role="alert">
                <strong>Error:</strong> @errorMessage
                <button class="btn btn-sm btn-outline-danger ms-2" @onclick="LoadProductsAsync">Retry</button>
            </div>
        }
        else if (products.Count == 0)
        {
            <div class="alert alert-info" role="alert">
                No products found matching your criteria. Try adjusting your filters.
            </div>
        }
        else
        {
            <CatalogToolbar SortBy="@sortBy"
                            TotalCount="totalCount"
                            Page="currentPage"
                            PageSize="pageSize"
                            OnSortChanged="HandleSortChanged" />

            <ProductGrid Products="products"
                         OnProductSelected="HandleProductSelected"
                         OnAddToCart="HandleAddToCart" />

            <CatalogPagination Page="currentPage"
                               TotalPages="totalPages"
                               OnPageChanged="HandlePageChanged" />
        }
    </div>
</div>

@code {
    private List<Product> products = [];
    private List<string> categories = [];
    private ProductFilter filter = new(null, null, null, false);
    private string sortBy = "price_asc";
    private int currentPage = 1;
    private int pageSize = 12;
    private int totalCount;
    private int totalPages;
    private bool loading = true;
    private string? errorMessage;

    protected override async Task OnInitializedAsync()
    {
        try
        {
            var categoriesTask = ProductService.GetCategoriesAsync();
            var productsTask = ProductService.SearchAsync(filter, sortBy, currentPage, pageSize);

            await Task.WhenAll(categoriesTask, productsTask);

            categories = await categoriesTask;
            ApplyResult(await productsTask);
        }
        catch (Exception ex)
        {
            errorMessage = ex.Message;
        }
        finally
        {
            loading = false;
        }
    }

    private async Task LoadProductsAsync()
    {
        loading = true;
        errorMessage = null;

        try
        {
            var result = await ProductService.SearchAsync(filter, sortBy, currentPage, pageSize);
            ApplyResult(result);
        }
        catch (Exception ex)
        {
            errorMessage = ex.Message;
        }
        finally
        {
            loading = false;
        }
    }

    private void ApplyResult(PagedResult<Product> result)
    {
        products = result.Items;
        totalCount = result.TotalCount;
        totalPages = (int)Math.Ceiling((double)result.TotalCount / pageSize);
    }

    private async Task HandleApplyFilters(ProductFilter newFilter)
    {
        filter = newFilter;
        currentPage = 1;
        await LoadProductsAsync();
    }

    private async Task HandleClearFilters()
    {
        filter = new(null, null, null, false);
        currentPage = 1;
        await LoadProductsAsync();
    }

    private async Task HandleSortChanged(string newSort)
    {
        sortBy = newSort;
        currentPage = 1;
        await LoadProductsAsync();
    }

    private async Task HandlePageChanged(int page)
    {
        currentPage = page;
        await LoadProductsAsync();
    }

    private Task HandleProductSelected(Product product)
    {
        // Parent can navigate: e.g., NavigationManager.NavigateTo($"/product/{product.Id}")
        return Task.CompletedTask;
    }

    private Task HandleAddToCart(Product product)
    {
        // Hook up to cart service when available
        return Task.CompletedTask;
    }
}

